// CredentialMutationServiceHandler is an implementation of the
// codewire.v1.CredentialMutationService service.
type CredentialMutationServiceHandler interface {
	// One connection owns the enrollment: one challenge followed by committed
	// metadata. Disconnect cancels unfinished enrollment, not an issued COMMIT.
	// Missing terminal metadata is an uncertain outcome: reconcile by name using
	// GetCredential, never automatically reenroll or revoke the provider login.
	EnrollCodex(context.Context, *connect.Request[v1.EnrollCodexRequest], *connect.ServerStream[v1.EnrollCodexResponse]) error
	// Same owned challenge/publication protocol, using the Codewire GitHub
	// App's device login. This remains the device-code path used by `cw`.
	EnrollGithub(context.Context, *connect.Request[v1.EnrollGithubRequest], *connect.ServerStream[v1.EnrollGithubResponse]) error
	// Browser GitHub connections use the configured GitHub App installation and
	// user-to-server callback flow. The authorization code is write-only and is
	// exchanged only by the isolated credential authority that holds the App
	// client secret; it never reaches a Sandbox or dashboard response. This
	// method requires the original browser session authority; the `cw` CLI uses
	// EnrollGithub's device-code path instead.
	CompleteGithubAppAuthorization(context.Context, *connect.Request[v1.CompleteGithubAppAuthorizationRequest]) (*connect.Response[v1.CompleteGithubAppAuthorizationResponse], error)
	AddApiKeyCredential(context.Context, *connect.Request[v1.AddApiKeyCredentialRequest]) (*connect.Response[v1.AddApiKeyCredentialResponse], error)
	// Write-only Claude subscription token import by paste. The owner runs
	// `claude setup-token` (Claude Pro, Max, Team or Enterprise) and supplies
	// the printed token; Codewire never runs Claude Code's OAuth client. The
	// server stores it as the anthropic provider's OAuth kind with a hard expiry
	// one year after this call. It is personal: organization API keys and
	// organizations are denied. The token is never returned, and it is never
	// delivered to a Sandbox: the credential broker injects it.
	AddClaudeSubscriptionTokenCredential(context.Context, *connect.Request[v1.AddClaudeSubscriptionTokenCredentialRequest]) (*connect.Response[v1.AddClaudeSubscriptionTokenCredentialResponse], error)
	// Claude sign-in: Claude Code's own claude.ai OAuth login, by pasted code.
	// Start creates this sign-in's PKCE verifier and state and returns Claude's
	// fixed authorize URL and an opaque handle; nothing is sent or stored. The
	// person signs in in their browser and copies the `code#state` Claude
	// shows. Complete checks that state against the handle, exchanges the code
	// as Claude Code's public client, reads the plan from Claude's OAuth
	// profile and stores the login as the anthropic provider's CLAUDE_SIGN_IN
	// kind. It is personal: organization API keys and organizations are denied.
	// No token is returned; the credential broker refreshes the login.
	StartClaudeSignIn(context.Context, *connect.Request[v1.StartClaudeSignInRequest]) (*connect.Response[v1.StartClaudeSignInResponse], error)
	CompleteClaudeSignIn(context.Context, *connect.Request[v1.CompleteClaudeSignInRequest]) (*connect.Response[v1.CompleteClaudeSignInResponse], error)
	RenameCredential(context.Context, *connect.Request[v1.RenameCredentialRequest]) (*connect.Response[v1.RenameCredentialResponse], error)
	RotateApiKeyCredential(context.Context, *connect.Request[v1.RotateApiKeyCredentialRequest]) (*connect.Response[v1.RotateApiKeyCredentialResponse], error)
	GenerateSshCredential(context.Context, *connect.Request[v1.GenerateSshCredentialRequest]) (*connect.Response[v1.GenerateSshCredentialResponse], error)
	AddSshCredential(context.Context, *connect.Request[v1.AddSshCredentialRequest]) (*connect.Response[v1.AddSshCredentialResponse], error)
	RevokeCredential(context.Context, *connect.Request[v1.RevokeCredentialRequest]) (*connect.Response[v1.RevokeCredentialResponse], error)
	DeleteCredential(context.Context, *connect.Request[v1.DeleteCredentialRequest]) (*connect.Response[v1.DeleteCredentialResponse], error)
}

